import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Activity, AlarmClock, Archive, ArrowDownRight, ArrowRight, ArrowUpRight, BarChart3,
  Bell, CalendarDays, Check, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight,
  CircleHelp, Clock3, Code2, Coffee, Command, Download, Flame, FolderKanban, Gauge,
  Goal, History, Home, Keyboard, Layers3, ListChecks, Moon, MoreHorizontal, Pause,
  Pencil, Play, Plus, Search, Settings2, ShieldCheck, Sparkles, Sun, Target,
  Timer, TrendingUp, Trophy, Upload, X, Zap, type LucideIcon,
} from 'lucide-react';
import {
  Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis,
} from 'recharts';

type Project = { id: string; name: string; category: string; color: string; target: number; batchSize: number; archived?: boolean };
type Batch = { id: string; projectId: string; date: string; tasks: number; planned: number; startedAt: number; endedAt: number; activeSeconds: number; breakSeconds: number; status: 'Completed' | 'Partial'; note?: string };
type Session = { id: string; projectId: string; planned: number; tasks: number; startedAt: number; activeSince: number | null; activeSeconds: number; breakSince: number | null; breakSeconds: number; paused: boolean; note: string };
type GoalSettings = { target: number; batchSize: number; plannedMinutes: number; notes: string };
type NavItem = { label: string; icon: LucideIcon; section: string };
type AppData = { version: 1; displayName: string; theme: 'dark' | 'light'; projects: Project[]; goals: Record<string, GoalSettings>; batches: Batch[]; session: Session | null; xpEvents: Record<string, number>; reflections: Record<string, { wentWell: string; slowedDown: string; improve: string; tomorrow: string }> };
const STORAGE = 'momentumflow-v1';
const todayKey = (at = new Date()) => `${at.getFullYear()}-${String(at.getMonth()+1).padStart(2,'0')}-${String(at.getDate()).padStart(2,'0')}`;
const makeId = () => globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2)}`;
const starter: AppData = {
  version: 1, displayName: 'Hemanth', theme: 'dark',
  projects: [
    { id: 'video', name: 'Video annotation', category: 'AI Operations', color: '#8a78ff', target: 800, batchSize: 100 },
    { id: 'audio', name: 'Audio annotation', category: 'AI Operations', color: '#29c6b7', target: 500, batchSize: 100 },
    { id: 'coding', name: 'Build MomentumFlow', category: 'Development', color: '#5da9ff', target: 3, batchSize: 1 },
  ],
  goals: {}, batches: [], session: null, xpEvents: {}, reflections: {},
};
function loadData(): AppData {
  try {
    const raw = localStorage.getItem(STORAGE);
    if (!raw) return starter;
    const parsed = JSON.parse(raw) as AppData;
    if (parsed.version !== 1 || !Array.isArray(parsed.projects) || !Array.isArray(parsed.batches)) return starter;
    return { ...starter, ...parsed, projects: parsed.projects, goals: parsed.goals ?? {}, batches: parsed.batches, xpEvents: parsed.xpEvents ?? {}, reflections: parsed.reflections ?? {} };
  } catch { return starter; }
}
const currentGoal = (data: AppData, project: Project, day = todayKey()): GoalSettings =>
  data.goals[`${project.id}:${day}`] ?? { target: project.target, batchSize: project.batchSize, plannedMinutes: 240, notes: '' };
const activeSecondsFor = (s: Session, now = Date.now()) => Math.max(0, s.activeSeconds + (s.activeSince ? Math.floor((now - s.activeSince) / 1000) : 0));
const breakSecondsFor = (s: Session, now = Date.now()) => Math.max(0, s.breakSeconds + (s.breakSince ? Math.floor((now - s.breakSince) / 1000) : 0));
const fmt = (n: number) => {
  const secs = Math.max(0, Math.floor(n));
  const h = Math.floor(secs/3600), m = Math.floor((secs%3600)/60), s = secs%60;
  return h ? `${h}h ${String(m).padStart(2,'0')}m` : `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;
};
const fmtClock = (n: number) => `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;
const shortDate = (day: string) => new Date(day+'T12:00:00').toLocaleDateString('en-IN', { month:'short', day:'numeric' });
const dateLabel = new Date().toLocaleDateString('en-IN', { weekday:'long', month:'long', day:'numeric', year:'numeric' });
const greeting = () => { const h = new Date().getHours(); return h < 12 ? 'Good morning' : h < 17 ? 'Good afternoon' : 'Good evening'; };
const initials = (name: string) => name.trim().split(/\s+/).slice(0,2).map(v=>v[0]?.toUpperCase() ?? '').join('') || 'MF';

export default function App() {
  const [data, setData] = useState<AppData>(loadData);
  const [now, setNow] = useState(Date.now());
  const [activeProject, setActiveProject] = useState(data.projects.find(p=>!p.archived)?.id ?? '');
  const [page, setPage] = useState('Dashboard');
  const [goalOpen, setGoalOpen] = useState(false);
  const [projectOpen, setProjectOpen] = useState(false);
  const [newProjectOpen, setNewProjectOpen] = useState(false);
  const [profileOpen, setProfileOpen] = useState(false);
  const [mobileNav, setMobileNav] = useState(false);
  const [toast, setToast] = useState('');
  const [search, setSearch] = useState('');
  const [historyFilter, setHistoryFilter] = useState<'All'|'Completed'|'Partial'>('All');
  const [range, setRange] = useState<'7 days'|'30 days'>('7 days');
  const [nameDraft, setNameDraft] = useState(data.displayName);
  const [projectDraft, setProjectDraft] = useState({ name: '', category: 'Custom', color: '#8a78ff', target: '500', batchSize: '100' });
  const [goalDraft, setGoalDraft] = useState<GoalSettings>({ target: 800, batchSize: 100, plannedMinutes: 240, notes: '' });
  const [taskDraft, setTaskDraft] = useState('100');
  const [noteDraft, setNoteDraft] = useState('');
  const [reflectionDraft, setReflectionDraft] = useState({ wentWell: '', slowedDown: '', improve: '', tomorrow: '800' });
  const [resetOpen, setResetOpen] = useState(false);

  const project = data.projects.find(p=>p.id===activeProject && !p.archived) ?? data.projects.find(p=>!p.archived) ?? data.projects[0];
  const day = todayKey();
  const goal = project ? currentGoal(data, project, day) : { target: 0, batchSize: 100, plannedMinutes: 240, notes: '' };
  const todaysBatches = useMemo(()=>data.batches.filter(b=>b.projectId===project?.id && b.date===day),[data.batches,project?.id,day]);
  const allTodayBatches = useMemo(()=>data.batches.filter(b=>b.date===day),[data.batches,day]);
  const completed = todaysBatches.reduce((sum,b)=>sum+b.tasks,0);
  const remaining = Math.max(0, goal.target-completed);
  const pct = goal.target > 0 ? completed/goal.target*100 : 0;
  const visualPct = Math.min(100,pct);
  const todayActive = todaysBatches.reduce((sum,b)=>sum+b.activeSeconds,0) + (data.session?.projectId===project?.id ? activeSecondsFor(data.session,now):0);
  const todayBreak = todaysBatches.reduce((sum,b)=>sum+b.breakSeconds,0) + (data.session?.projectId===project?.id ? breakSecondsFor(data.session,now):0);
  const rate = todayActive > 0 ? completed/(todayActive/3600) : 0;
  const etaSeconds = rate > 0 && remaining > 0 ? remaining/rate*3600 : 0;
  const session = data.session;
  const sessionActive = session ? activeSecondsFor(session,now) : 0;
  const sessionBreak = session ? breakSecondsFor(session,now) : 0;
  const currentSessionProject = session ? data.projects.find(p=>p.id===session.projectId) : null;
  const totalXp = Object.values(data.xpEvents).reduce((s,n)=>s+n,0);
  const level = Math.floor(totalXp/250)+1;
  const levelXp = totalXp%250;
  const currentReflection = data.reflections[day] ?? { wentWell:'', slowedDown:'', improve:'', tomorrow:String(goal.target || 800) };
  const [weeklyStats, setWeeklyStats] = useState<{day:string;tasks:number;active:number}[]>([]);
  const update = useCallback((fn: (prev: AppData)=>AppData) => setData(prev=>fn(prev)), []);
  const notify = useCallback((message: string) => { setToast(message); window.setTimeout(()=>setToast(''),3000); }, []);

  useEffect(()=>{ localStorage.setItem(STORAGE, JSON.stringify(data)); document.documentElement.dataset.theme=data.theme; },[data]);
  useEffect(()=>{ const id=window.setInterval(()=>setNow(Date.now()),1000); const focus=()=>setNow(Date.now()); window.addEventListener('focus',focus); return ()=>{clearInterval(id);window.removeEventListener('focus',focus);}; },[]);
  useEffect(()=>{ setGoalDraft(goal); },[project?.id, goal.target, goal.batchSize, goal.plannedMinutes, goal.notes]);
  useEffect(()=>{ setReflectionDraft(currentReflection); },[day,project?.id]);
  useEffect(()=>{
    const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));return todayKey(d);});
    setWeeklyStats(days.map(d=>({day:shortDate(d),tasks:data.batches.filter(b=>b.date===d).reduce((n,b)=>n+b.tasks,0),active:data.batches.filter(b=>b.date===d).reduce((n,b)=>n+b.activeSeconds,0)})));
  },[data.batches,now]);
  useEffect(()=>{ if(session && !data.projects.some(p=>p.id===session.projectId && !p.archived)){ notify('Your active project was archived. Resume from the session panel when ready.'); } },[data.projects,session,notify]);

  const navigate = (label:string) => { setPage(label);setMobileNav(false); };
  const saveGoal = () => {
    if(!project || !Number.isFinite(goalDraft.target) || goalDraft.target<0 || !Number.isFinite(goalDraft.batchSize) || goalDraft.batchSize<1 || !Number.isFinite(goalDraft.plannedMinutes) || goalDraft.plannedMinutes<1) { notify('Enter a valid target, batch size and planned duration.');return; }
    update(d=>({...d,goals:{...d.goals,[`${project.id}:${day}`]:{...goalDraft,target:Math.floor(goalDraft.target),batchSize:Math.floor(goalDraft.batchSize)}}}));
    setGoalOpen(false);notify('Daily goal updated.');
  };
  const startSession = () => {
    if(!project || (session && !session.paused && !session.breakSince)) { notify('Finish or pause your current session before starting another.');return; }
    if(session && session.paused && session.projectId!==project.id) { notify('Resume or finish the current session before switching projects.');return; }
    if(session) {
      update(d=>({...d,session:{...session,paused:false,activeSince:Date.now()}}));notify('Session resumed. Welcome back.');return;
    }
    const s:Session={id:makeId(),projectId:project.id,planned:goal.batchSize,tasks:0,startedAt:Date.now(),activeSince:Date.now(),activeSeconds:0,breakSince:null,breakSeconds:0,paused:false,note:''};
    update(d=>({...d,session:s}));setTaskDraft(String(goal.batchSize));notify('Focus session started. One batch at a time.');
  };
  const pauseSession = () => {
    if(!session || session.paused || session.breakSince) return;
    const at=Date.now();update(d=>({...d,session:d.session?{...d.session,activeSeconds:activeSecondsFor(d.session,at),activeSince:null,paused:true}:null}));notify('Session paused. Your active time is saved.');
  };
  const resumeSession = () => {
    if(!session || (!session.paused && !session.breakSince)) return;
    const at=Date.now();update(d=>({...d,session:d.session?{...d.session,paused:false,activeSince:at,breakSince:null}:null}));notify('Back in focus. Let’s continue.');
  };
  const startBreak = () => {
    if(!session || session.paused || session.breakSince) return;
    const at=Date.now();update(d=>({...d,session:d.session?{...d.session,activeSeconds:activeSecondsFor(d.session,at),activeSince:null,breakSince:at}:null}));notify('Break started. Take the time you need.');
  };
  const finishBatch = (partial = false) => {
    if(!session) return;
    const at=Date.now(); const nextTasks=Number(taskDraft);
    if(!Number.isFinite(nextTasks) || nextTasks<0 || !Number.isInteger(nextTasks)) { notify('Enter a whole number of completed tasks.');return; }
    const active=activeSecondsFor(session,at), breaks=breakSecondsFor(session,at), tasks=nextTasks;
    if(tasks===0 && !partial && !window.confirm('This batch has 0 completed tasks. Save the time as a partial record?')) return;
    const record:Batch={id:session.id,projectId:session.projectId,date:todayKey(new Date(session.startedAt)),tasks,planned:session.planned,startedAt:session.startedAt,endedAt:at,activeSeconds:active,breakSeconds:breaks,status:partial||tasks<session.planned?'Partial':'Completed',note:noteDraft.trim()||session.note};
    const eventKey='batch:'+record.id;
    update(d=>({...d,batches:[record,...d.batches.filter(b=>b.id!==record.id)],session:null,xpEvents:{...d.xpEvents,[eventKey]:Math.max(0,tasks)*1+(tasks>=session.planned?20:5)}}));
    setTaskDraft(String(goal.batchSize));setNoteDraft('');
    notify(tasks>=session.planned?'Batch completed. You earned progress and XP.':'Batch saved with actual progress. Every task counts.');
  };
  const cancelSession = () => {
    if(!session) return;
    if(!window.confirm('Cancel this session without adding it to your batch history?')) return;
    update(d=>({...d,session:null}));notify('Session cancelled; no batch was recorded.');
  };
  const addProject = () => {
    const target=Number(projectDraft.target),size=Number(projectDraft.batchSize);
    if(!projectDraft.name.trim() || !Number.isFinite(target)||target<0||!Number.isFinite(size)||size<1){notify('Add a project name, valid goal and batch size.');return;}
    const p:Project={id:makeId(),name:projectDraft.name.trim(),category:projectDraft.category,color:projectDraft.color,target:Math.floor(target),batchSize:Math.floor(size)};
    update(d=>({...d,projects:[...d.projects,p]}));setActiveProject(p.id);setProjectDraft({name:'',category:'Custom',color:'#8a78ff',target:'500',batchSize:'100'});setNewProjectOpen(false);navigate('Dashboard');notify('Project created.');
  };
  const saveReflection = () => {update(d=>({...d,reflections:{...d.reflections,[day]:reflectionDraft}}));notify('Daily reflection saved.');};
  const exportData = () => {
    const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`momentumflow-backup-${day}.json`;a.click();URL.revokeObjectURL(url);notify('Backup exported.');
  };
  const importData = (file?:File) => {
    if(!file) return;
    const reader=new FileReader();reader.onload=()=>{try {const p=JSON.parse(String(reader.result)) as AppData;if(p.version!==1||!Array.isArray(p.projects)||!Array.isArray(p.batches)||!p.goals||!p.xpEvents)throw new Error('invalid');if(!window.confirm('Import this backup and replace your current MomentumFlow data? Download a backup first if you need one.'))return;setData({...starter,...p});setActiveProject(p.projects.find(x=>!x.archived)?.id??'');notify('Backup imported.');}catch{notify('That file is not a valid MomentumFlow v1 backup.');}};reader.readAsText(file);
  };
  const deleteBatch = (id:string) => {if(!window.confirm('Delete this batch from history? The dashboard totals will be recalculated.'))return;update(d=>({...d,batches:d.batches.filter(b=>b.id!==id),xpEvents:Object.fromEntries(Object.entries(d.xpEvents).filter(([k])=>k!=='batch:'+id))}));notify('Batch deleted.');};
  const allTasks = data.batches.reduce((s,b)=>s+b.tasks,0);
  const allActive = data.batches.reduce((s,b)=>s+b.activeSeconds,0);
  const averageRate = allActive>0 ? allTasks/(allActive/3600):0;
  const dayStart=new Date();dayStart.setHours(0,0,0,0);
  const streak = (()=>{let n=0;for(let offset=0;offset<365;offset++){const d=new Date();d.setDate(d.getDate()-offset);const k=todayKey(d);if(data.batches.some(b=>b.date===k&&b.tasks>0))n++;else if(offset===0)continue;else break;}return n;})();
  const nav:NavItem[]=[
    {label:'Dashboard',icon:Home,section:'WORKSPACE'},
    {label:'My Projects',icon:FolderKanban,section:'WORKSPACE'},
    {label:'Focus Session',icon:Timer,section:'WORKSPACE'},
    {label:'Batch History',icon:History,section:'TRACK'},
    {label:'Analytics',icon:BarChart3,section:'TRACK'},
    {label:'Achievements',icon:Trophy,section:'TRACK'},
    {label:'Daily Reports',icon:CalendarDays,section:'TRACK'},
    {label:'Settings',icon:Settings2,section:'PREFERENCES'},
  ];
  const navSections=['WORKSPACE','TRACK','PREFERENCES'];
  const navButton=(item:NavItem)=> <button key={item.label} className={`nav-item ${page===item.label?'active':''}`} onClick={()=>navigate(item.label)}><item.icon size={17}/><span>{item.label}</span>{item.label==='Focus Session'&&session?<i className="live-dot"/>:null}</button>;
  const trend=weeklyStats.length>1&&weeklyStats[5].tasks>0?Math.round((weeklyStats[6].tasks-weeklyStats[5].tasks)/Math.max(1,weeklyStats[5].tasks)*100):0;
  const IconButton=({label,children,onClick}:{label:string;children:React.ReactNode;onClick:()=>void})=><button className="icon-button" aria-label={label} title={label} onClick={onClick}>{children}</button>;

  return <div className="app-shell">
    <aside className={`sidebar ${mobileNav?'mobile-open':''}`}>
      <div className="brand"><div className="brand-mark"><Command size={19} strokeWidth={2.8}/><span/></div><div><strong>momentum<span>flow</span></strong><small>PERSONAL COMMAND CENTER</small></div><button className="sidebar-close" onClick={()=>setMobileNav(false)} aria-label="Close navigation"><X size={17}/></button></div>
      <button className="workspace-switch" onClick={()=>setProjectOpen(v=>!v)}><span className="workspace-avatar">M</span><span className="workspace-copy"><b>My workspace</b><small>{data.projects.filter(p=>!p.archived).length} active projects</small></span><ChevronDown size={15}/></button>
      {projectOpen&&<div className="workspace-popover">{data.projects.filter(p=>!p.archived).map(p=><button key={p.id} onClick={()=>{setActiveProject(p.id);setProjectOpen(false)}}><i style={{background:p.color}}/>{p.name}{activeProject===p.id&&<Check size={14}/>}</button>)}<button onClick={()=>{setNewProjectOpen(true);setProjectOpen(false)}}><Plus size={14}/> Add project</button></div>}
      <button className="new-session-button" onClick={()=>{navigate('Focus Session');if(!session)startSession()}}><span><Play size={15} fill="currentColor"/></span> Start focus session <kbd>⌘ K</kbd></button>
      <div className="nav-groups">{navSections.map(section=><div className="nav-group" key={section}><p className="nav-heading">{section}</p>{nav.filter(n=>n.section===section).map(navButton)}</div>)}</div>
      <div className="sidebar-bottom"><div className="streak-mini"><div className="streak-icon"><Flame size={17} fill="currentColor"/></div><div><b>{streak} day streak</b><small>{streak?'Keep your rhythm going':'Your first streak starts today'}</small></div><ChevronRight size={15}/></div><div className="sidebar-profile"><div className="profile-avatar">{initials(data.displayName)}</div><div className="profile-copy"><b>{data.displayName}</b><small>Level {level} · {totalXp} XP</small></div><button className="dots-button" onClick={()=>setProfileOpen(v=>!v)} aria-label="Profile options"><MoreHorizontal size={18}/></button>{profileOpen&&<div className="profile-popover"><button onClick={()=>{navigate('Settings');setProfileOpen(false)}}><Settings2 size={15}/> Profile settings</button><button onClick={exportData}><Download size={15}/> Export backup</button></div>}</div></div>
    </aside>
    {mobileNav&&<button className="mobile-backdrop" aria-label="Close menu" onClick={()=>setMobileNav(false)}/>}
    <main className="main-area">
      <header className="topbar"><div className="breadcrumbs"><button className="mobile-menu" onClick={()=>setMobileNav(true)} aria-label="Open navigation"><Layers3 size={19}/></button><span>Workspace</span><ChevronRight size={14}/><strong>{page}</strong></div><div className="top-actions"><span className="top-date"><CalendarDays size={15}/>{new Date().toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'short'})}</span><span className="top-divider"/><IconButton label="Search batches" onClick={()=>{navigate('Batch History');window.setTimeout(()=>document.getElementById('history-search')?.focus(),80)}}><Search size={17}/></IconButton><IconButton label={data.theme==='dark'?'Switch to light mode':'Switch to dark mode'} onClick={()=>update(d=>({...d,theme:d.theme==='dark'?'light':'dark'}))}>{data.theme==='dark'?<Sun size={17}/>:<Moon size={17}/>}</IconButton><button className="top-avatar" onClick={()=>{navigate('Settings')}}>{initials(data.displayName)}</button></div></header>
      <div className="page-content">
        {page==='Dashboard'&&<><div className="page-intro"><div><div className="eyebrow"><span className="eyebrow-dot"/>{dateLabel}</div><h1>{greeting()}, {data.displayName.split(' ')[0]} <span className="greeting-spark">✳</span></h1><p>A little progress, repeated daily, adds up to remarkable results.</p></div><div className="intro-actions"><button className="button button-secondary" onClick={()=>{setGoalDraft(goal);setGoalOpen(true)}}><Pencil size={15}/> Edit daily goal</button><button className="button button-primary" onClick={()=>{navigate('Focus Session');if(!session)startSession()}}><Play size={15} fill="currentColor"/> {session?'View active session':'Start focusing'}<ArrowRight size={15}/></button></div></div>
          <div className="dashboard-grid"><section className="goal-card card"><div className="card-top"><div><div className="section-kicker"><Target size={15}/> YOUR DAILY GOAL</div><h2>Make today count<span className="title-dot">.</span></h2><p className="muted small">Small batches. Meaningful progress.</p></div><button className="project-chip" onClick={()=>setProjectOpen(v=>!v)}><i style={{background:project?.color}}/>{project?.name??'Select project'}<ChevronDown size={13}/></button></div>
            <div className="goal-main"><div className="goal-ring" style={{'--progress':`${visualPct*3.6}deg`} as React.CSSProperties}><div className="goal-ring-inner"><span className="ring-symbol"><Target size={16}/></span><strong>{Math.round(visualPct)}<small>%</small></strong><span>completed</span></div></div><div className="goal-numbers"><span className="mini-label">TASKS COMPLETED</span><div className="big-number">{completed.toLocaleString('en-IN')}<span> / {goal.target.toLocaleString('en-IN')}</span></div><div className="progress-track"><div className="progress-fill" style={{width:`${visualPct}%`}}/></div><div className="progress-meta"><span><i className="legend-dot purple"/>Daily progress</span><strong>{remaining.toLocaleString('en-IN')} left</strong></div><div className="goal-status"><span className={`status-pill ${pct>=100?'success':pct>=50?'progressing':'neutral'}`}>{pct>=100?'Goal achieved':pct>=75?'Almost there':pct>=50?'Halfway there':pct>0?'Building momentum':'Ready when you are'}</span>{pct>100&&<span className="over-target">+{Math.floor(pct-100)}% over target</span>}</div></div></div>
            <div className="goal-footer"><div><Clock3 size={15}/><span>Planned work</span><b>{Math.floor(goal.plannedMinutes/60)}h {goal.plannedMinutes%60?goal.plannedMinutes%60+'m':''}</b></div><span className="footer-separator"/><div><Gauge size={15}/><span>Observed pace</span><b>{rate>0?`${rate.toFixed(1)} tasks/hr`:'Not enough data yet'}</b></div><span className="footer-separator"/><div><AlarmClock size={15}/><span>Active time</span><b>{fmt(todayActive)}</b></div></div>
          </section>
          <section className="focus-card card"><div className="focus-heading"><div><div className="section-kicker"><span className={session?'eyebrow-dot live':'focus-dot'}/>{session?'SESSION IN PROGRESS':'FOCUS SPACE'}</div><h3>{session?'Stay in your flow':'Ready for a focus block?'}</h3></div><span className="focus-status">{session?.breakSince?'On break':session?.paused?'Paused':session?'● Live':'○ Ready'}</span></div>
            <div className={`timer-disc ${session?'timer-active':''} ${session?.breakSince?'timer-break':''}`}><div className="timer-halo"/><div className="timer-content"><span>{session?.breakSince?'BREAK TIME':session?.paused?'SESSION PAUSED':'ACTIVE FOCUS'}</span><strong>{fmt(session?sessionActive:0)}</strong><small>{session? `Batch ${todaysBatches.length+1} · ${currentSessionProject?.name??'Current project'}`:'Your next productive minute starts here'}</small></div></div>
            {session?<><div className="session-progress"><div className="session-progress-label"><span>Batch progress</span><b>{session.tasks} <small>/ {session.planned}</small></b></div><div className="progress-track"><div className="progress-fill teal" style={{width:`${Math.min(100,session.tasks/Math.max(1,session.planned)*100)}%`}}/></div></div><div className="focus-controls">{session.paused||session.breakSince?<button className="button button-primary full-button" onClick={resumeSession}><Play size={15} fill="currentColor"/> Resume focus</button>:<><button className="button button-secondary" onClick={pauseSession}><Pause size={15}/> Pause</button><button className="button button-secondary" onClick={startBreak} disabled={!!session.breakSince}><Coffee size={15}/> Break</button><button className="button button-primary finish-button" onClick={()=>{setTaskDraft(String(session.tasks||session.planned));navigate('Focus Session')}}><Check size={15}/> Finish batch</button></>}</div></>:<><p className="focus-description">Start a session when you're ready. Your active time is tracked separately from breaks.</p><button className="button button-primary full-button" onClick={startSession}><Play size={15} fill="currentColor"/> Start a focus session <ArrowRight size={15}/></button></>}
            <div className="focus-bottom"><span><ShieldCheck size={14}/> Time tracking saves automatically</span><span><Coffee size={14}/> Breaks don't count as work</span></div>
          </section></div>
          <div className="stat-grid"><StatCard icon={ListChecks} iconClass="stat-purple" label="Completed tasks" value={completed.toLocaleString('en-IN')} trend={goal.target?Math.round(pct)+'% of goal':'Set a target'} trendUp={pct>0} foot="for the selected project" /><StatCard icon={Clock3} iconClass="stat-blue" label="Active work time" value={fmt(todayActive)} trend={todayBreak>0?fmt(todayBreak)+' break':'Breaks excluded'} trendUp={false} foot="today · focus time only" /><StatCard icon={TrendingUp} iconClass="stat-green" label="Tasks per hour" value={rate>0?rate.toFixed(1):'—'} trend={rate>0?'Observed pace':'Needs completed work'} trendUp={rate>0} foot="based on active work time" /><StatCard icon={Flame} iconClass="stat-orange" label="Current streak" value={String(streak)} trend={streak?'Keep it going':'Start your streak'} trendUp={streak>0} foot="days with completed work" /></div>
          <div className="bottom-grid"><section className="card chart-card"><div className="card-heading"><div><div className="section-kicker"><Activity size={14}/> YOUR MOMENTUM</div><h3>Work at your own pace</h3><p className="muted small">Real completed tasks across the last 7 days.</p></div><button className="text-button" onClick={()=>navigate('Analytics')}>Full analytics <ArrowRight size={14}/></button></div><div className="chart-wrap">{weeklyStats.every(s=>s.tasks===0)?<EmptyState icon={BarChart3} title="Your week starts here" detail="Finish your first batch to see your real activity trend."/>:<ResponsiveContainer width="100%" height="100%"><AreaChart data={weeklyStats} margin={{top:10,right:6,left:-18,bottom:0}}><defs><linearGradient id="tasksGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#8b78ff" stopOpacity={0.29}/><stop offset="95%" stopColor="#8b78ff" stopOpacity={0.01}/></linearGradient></defs><CartesianGrid stroke="var(--chart-grid)" vertical={false}/><XAxis dataKey="day" tick={{fill:'var(--text-muted)',fontSize:11}} axisLine={false} tickLine={false} dy={9}/><YAxis tick={{fill:'var(--text-muted)',fontSize:11}} axisLine={false} tickLine={false} allowDecimals={false}/><Tooltip contentStyle={{background:'var(--popover)',border:'1px solid var(--border)',borderRadius:12,color:'var(--text)',fontSize:12}} formatter={(value:number)=>[value.toLocaleString()+' tasks','Completed']} /><Area type="monotone" dataKey="tasks" stroke="#927dff" strokeWidth={2.5} fill="url(#tasksGradient)" activeDot={{r:4,strokeWidth:0,fill:'#b8aaff'}}/></AreaChart></ResponsiveContainer>}</div><div className="chart-foot"><span><i className="legend-dot purple"/>Tasks completed</span><span className="chart-foot-note">No demo data · based on your history</span></div></section>
            <section className="card batches-card"><div className="card-heading"><div><div className="section-kicker"><Layers3 size={14}/> RECENT ACTIVITY</div><h3>Recent batches</h3></div><button className="icon-button subtle" aria-label="View batch history" onClick={()=>navigate('Batch History')}><ArrowRight size={16}/></button></div>{data.batches.filter(b=>b.projectId===project?.id).slice(0,4).length===0?<div className="batch-empty"><div className="empty-icon"><Layers3 size={20}/></div><b>No batches yet</b><span>Your completed batches will show up here.</span><button className="text-button" onClick={()=>{navigate('Focus Session');if(!session)startSession()}}>Start your first batch <ArrowRight size={13}/></button></div>:<div className="recent-list">{data.batches.filter(b=>b.projectId===project?.id).slice(0,4).map(b=><div className="recent-row" key={b.id}><div className="batch-icon"><CheckCircle2 size={16}/></div><div className="recent-copy"><b>{b.tasks} tasks completed</b><span>{shortDate(b.date)} · {fmt(b.activeSeconds)} active</span></div><span className={`batch-tag ${b.status==='Completed'?'tag-done':'tag-partial'}`}>{b.status}</span></div>)}</div>}<button className="button button-secondary full-button view-history" onClick={()=>navigate('Batch History')}>View all batch history <ArrowRight size={14}/></button></section></div>
          <div className="motivation-banner"><div className="motivation-icon"><Sparkles size={22}/></div><div><span className="section-kicker">A NOTE FOR TODAY</span><h3>{pct>=100?'Daily target achieved. You followed through.':completed>0?remaining>0?'Your effort is adding up. Keep the next step manageable.':'You’ve made real progress today.':session?'You showed up. Stay with the next manageable step.':'One batch at a time. Let’s get moving.'}</h3><p>{completed>0?`${completed.toLocaleString('en-IN')} tasks recorded for ${project?.name??'this project'} today. Progress doesn't have to be perfect to count.`:'Start small. The best system is one that helps you return to what matters.'}</p></div><div className="motivation-progress"><strong>{totalXp} <span>XP</span></strong><span>lifetime experience</span><div className="xp-track"><div style={{width:`${levelXp/250*100}%`}}/></div><small>Level {level} · {250-levelXp} XP to next</small></div></div>
        </>}
        {page==='My Projects'&&<><PageIntro eyebrow="YOUR WORKSPACE" title="Projects" subtitle="Keep every kind of work organized, measured and moving." action={<button className="button button-primary" onClick={()=>setNewProjectOpen(true)}><Plus size={15}/> New project</button>}/><div className="projects-summary"><div className="summary-chip"><FolderKanban size={16}/><span>{data.projects.filter(p=>!p.archived).length} active projects</span></div><div className="summary-chip"><ListChecks size={16}/><span>{allTasks.toLocaleString()} tasks completed overall</span></div><div className="summary-chip"><Clock3 size={16}/><span>{fmt(allActive)} active time recorded</span></div></div><div className="project-grid">{data.projects.filter(p=>!p.archived).map(p=>{const target=currentGoal(data,p);const done=data.batches.filter(b=>b.projectId===p.id&&b.date===day).reduce((n,b)=>n+b.tasks,0);const count=data.batches.filter(b=>b.projectId===p.id).length;return <article className="project-card card" key={p.id}><div className="project-card-top"><div className="project-symbol" style={{background:`${p.color}20`,color:p.color}}><Code2 size={21}/></div><button className="icon-button subtle" aria-label={'Archive '+p.name} onClick={()=>{if(window.confirm(`Archive "${p.name}"? Its history will be kept.`)){update(d=>({...d,projects:d.projects.map(x=>x.id===p.id?{...x,archived:true}:x)}));if(activeProject===p.id)setActiveProject(data.projects.find(x=>x.id!==p.id&&!x.archived)?.id??'');notify('Project archived. History is preserved.');}}}><Archive size={16}/></button></div><span className="project-category">{p.category}</span><h3>{p.name}</h3><p>{p.id==='video'?'Review visual data with consistency and care.':p.id==='audio'?'Build accurate audio labels, one batch at a time.':p.id==='coding'?'Ship features and learn through focused work.':'Your dedicated space to make steady progress.'}</p><div className="project-metrics"><div><span>TODAY</span><b>{done.toLocaleString()} <small>/ {target.target.toLocaleString()}</small></b></div><div><span>BATCHES</span><b>{count}</b></div></div><div className="progress-track project-track"><div className="progress-fill" style={{background:p.color,width:`${Math.min(100,target.target?done/target.target*100:0)}%`}}/></div><button className={`button ${activeProject===p.id?'button-secondary':'button-primary'} full-button project-select`} onClick={()=>{setActiveProject(p.id);navigate('Dashboard')}}>{activeProject===p.id?<><Check size={15}/> Current project</>:<>Open project <ArrowRight size={14}/></>}</button></article>})}<button className="project-add-card" onClick={()=>setNewProjectOpen(true)}><span><Plus size={21}/></span><b>Create a new project</b><small>Make room for your next goal</small></button></div><section className="card archived-panel"><h3>Archived projects</h3>{data.projects.filter(p=>p.archived).length?data.projects.filter(p=>p.archived).map(p=><div className="archived-row" key={p.id}><i style={{background:p.color}}/><span>{p.name}</span><button className="text-button" onClick={()=>{update(d=>({...d,projects:d.projects.map(x=>x.id===p.id?{...x,archived:false}:x)}));notify('Project restored.')}}>Restore</button></div>):<p className="muted small">Archived projects remain here, with their history preserved.</p>}</section></>}
        {page==='Focus Session'&&<><PageIntro eyebrow="DEEP WORK, YOUR WAY" title="Focus session" subtitle="Focus on the work, not the clock. Active work and breaks are tracked separately." action={<span className="session-safe-pill"><ShieldCheck size={15}/> Auto-saved locally</span>}/>{session?<div className="session-workspace"><section className="card session-main-card"><div className="session-large-header"><div><span className="section-kicker"><span className={session.breakSince?'break-dot':session.paused?'paused-dot':'eyebrow-dot'}/>{session.breakSince?'BREAK IN PROGRESS':session.paused?'SESSION PAUSED':'LIVE SESSION'}</span><h2>{currentSessionProject?.name??'Archived project session'}</h2><p>Session began at {new Date(session.startedAt).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}</p></div><span className="session-id">#{session.id.slice(0,6).toUpperCase()}</span></div><div className="session-time-layout"><div className="session-big-ring"><div><span>ACTIVE WORK</span><strong>{fmt(sessionActive)}</strong><small>Breaks excluded</small></div></div><div className="session-metrics"><div><span>Wall-clock time</span><strong>{fmt(Math.floor((now-session.startedAt)/1000))}</strong></div><div><span>Break time</span><strong>{fmt(sessionBreak)}</strong></div><div><span>Tasks recorded</span><strong>{session.tasks}</strong></div><div><span>Planned batch</span><strong>{session.planned}</strong></div></div></div><div className="session-entry-grid"><label>Tasks completed<input type="number" min="0" step="1" value={taskDraft} onChange={e=>setTaskDraft(e.target.value)} placeholder="Actual completed tasks"/></label><label>Batch note (optional)<input value={noteDraft} onChange={e=>setNoteDraft(e.target.value)} placeholder="Any useful notes…"/></label></div><div className="session-actions">{session.paused||session.breakSince?<button className="button button-primary" onClick={resumeSession}><Play size={15} fill="currentColor"/> Resume session</button>:<><button className="button button-secondary" onClick={pauseSession}><Pause size={15}/> Pause</button><button className="button button-secondary" onClick={startBreak} disabled={!!session.breakSince}><Coffee size={15}/> Start a break</button></>}<button className="button button-primary" onClick={()=>finishBatch(true)}><CheckCircle2 size={15}/> Save batch</button><button className="button button-danger" onClick={cancelSession}>Cancel</button></div><p className="privacy-note"><ShieldCheck size={14}/> This session survives page refreshes. Everything is saved in this browser, not synced to a server.</p></section><aside className="session-side"><section className="card session-side-card"><div className="section-kicker"><Target size={14}/> TODAY'S TARGET</div><div className="session-side-number">{completed.toLocaleString()} <span>/ {goal.target.toLocaleString()} tasks</span></div><div className="progress-track"><div className="progress-fill teal" style={{width:`${visualPct}%`}}/></div><div className="session-side-foot"><span>{remaining.toLocaleString()} remaining</span><b>{Math.round(visualPct)}%</b></div></section><section className="card session-side-card"><div className="section-kicker"><Coffee size={14}/> HEALTHY RHYTHM</div><h3>Breaks are part of the plan.</h3><p className="muted small">Your active pace only includes time actually spent working. Take a breather when you need one.</p><button className="button button-secondary full-button" onClick={startBreak} disabled={!!session.breakSince||session.paused}><Coffee size={15}/> Take a break</button></section><section className="card session-side-card"><div className="section-kicker"><Zap size={14}/> SESSION GUIDE</div><ul className="session-guide"><li><span>01</span> Work on one manageable batch.</li><li><span>02</span> Log the number actually completed.</li><li><span>03</span> Save the batch to update insights.</li></ul></section></aside></div>:<div className="focus-empty-layout"><section className="card focus-empty-card"><div className="big-focus-symbol"><div><Timer size={38}/></div><span/><i/></div><span className="section-kicker">YOUR NEXT FOCUS BLOCK</span><h2>Make space for focused work.</h2><p>Choose your project, start a session, and let MomentumFlow keep an honest record of your work time, breaks, and actual progress.</p><div className="focus-empty-setup"><label>Working on<select value={activeProject} onChange={e=>setActiveProject(e.target.value)}>{data.projects.filter(p=>!p.archived).map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><div><span>Default batch size</span><b>{goal.batchSize} tasks</b></div><div><span>Today's target</span><b>{goal.target.toLocaleString()} tasks</b></div></div><button className="button button-primary start-big-button" onClick={startSession}><Play size={17} fill="currentColor"/> Start focus session <ArrowRight size={16}/></button><span className="focus-empty-foot"><ShieldCheck size={14}/> Your progress is saved to this browser automatically</span></section><aside className="focus-side-stack"><section className="card side-tip"><span className="tip-icon"><Sparkles size={18}/></span><h3>Start smaller than you think.</h3><p>The first step is simply to begin. Your batch can be any size that makes sense for the work.</p></section><section className="card side-tip"><span className="tip-icon green"><Coffee size={18}/></span><h3>Rest is productive, too.</h3><p>Pause or start a break whenever you need. Neither one increases your active-work timer.</p></section></aside></div>}</>}
        {page==='Batch History'&&<><PageIntro eyebrow="YOUR WORK, RECORDED" title="Batch history" subtitle="An honest record of what you completed and the time you spent." action={<button className="button button-secondary" onClick={exportData}><Download size={15}/> Export data</button>}/><div className="history-stats"><div className="card history-stat"><span>Total recorded tasks</span><b>{allTasks.toLocaleString()}</b></div><div className="card history-stat"><span>Saved batches</span><b>{data.batches.length}</b></div><div className="card history-stat"><span>Active work time</span><b>{fmt(allActive)}</b></div><div className="card history-stat"><span>Observed average pace</span><b>{averageRate>0?averageRate.toFixed(1):'—'} <small>{averageRate>0?'tasks/hr':''}</small></b></div></div><section className="card history-card"><div className="history-tools"><div className="search-field"><Search size={16}/><input id="history-search" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search projects or batch notes…"/></div><div className="filter-tabs">{(['All','Completed','Partial'] as const).map(f=><button className={historyFilter===f?'selected':''} key={f} onClick={()=>setHistoryFilter(f)}>{f}</button>)}</div></div>{(()=>{const items=data.batches.filter(b=>(historyFilter==='All'||b.status===historyFilter)&&(`${data.projects.find(p=>p.id===b.projectId)?.name??''} ${b.note??''} ${b.id}`).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.endedAt-a.endedAt);return items.length?<div className="table-scroll"><table className="data-table"><thead><tr><th>BATCH / PROJECT</th><th>DATE</th><th>COMPLETED</th><th>ACTIVE TIME</th><th>BREAKS</th><th>PACE</th><th>STATUS</th><th/></tr></thead><tbody>{items.map(b=><tr key={b.id}><td><div className="history-project"><span className="batch-icon"><Layers3 size={15}/></span><div><b>{b.id===b.id?'Batch #'+b.id.slice(0,6).toUpperCase():''}</b><small>{data.projects.find(p=>p.id===b.projectId)?.name??'Archived project'}{b.note?' · '+b.note:''}</small></div></div></td><td>{shortDate(b.date)}</td><td><b>{b.tasks}</b> <span className="muted">/ {b.planned}</span></td><td>{fmt(b.activeSeconds)}</td><td>{fmt(b.breakSeconds)}</td><td>{b.activeSeconds>0?(b.tasks/(b.activeSeconds/3600)).toFixed(1)+' /hr':'—'}</td><td><span className={`batch-tag ${b.status==='Completed'?'tag-done':'tag-partial'}`}>{b.status}</span></td><td><button className="icon-button subtle danger-hover" title="Delete batch" aria-label="Delete batch" onClick={()=>deleteBatch(b.id)}><X size={15}/></button></td></tr>)}</tbody></table></div>:<EmptyState icon={History} title="No matching batches" detail="Finish a focus session and it will appear here with its real time and task count."/>})()}</section><div className="history-disclaimer"><ShieldCheck size={15}/> Historical times are stored locally. Pauses and breaks are excluded from active-work duration.</div></>}
        {page==='Analytics'&&<><PageIntro eyebrow="INSIGHTS, NOT PRESSURE" title="Analytics" subtitle="Look back at your real activity and find a rhythm that works for you." action={<div className="filter-tabs">{(['7 days','30 days'] as const).map(x=><button className={range===x?'selected':''} key={x} onClick={()=>setRange(x)}>{x}</button>)}</div>}/><div className="stat-grid analytics-stats"><StatCard icon={ListChecks} iconClass="stat-purple" label="Tasks recorded" value={allTasks.toLocaleString()} trend="Lifetime total" foot="from saved batches"/><StatCard icon={Clock3} iconClass="stat-blue" label="Active work" value={fmt(allActive)} trend="Breaks excluded" foot="lifetime recorded work"/><StatCard icon={Gauge} iconClass="stat-green" label="Average pace" value={averageRate?averageRate.toFixed(1):'—'} trend={averageRate?'tasks per active hour':'Not enough data'} foot="actual tasks ÷ active hours"/><StatCard icon={Layers3} iconClass="stat-orange" label="Batch count" value={String(data.batches.length)} trend={data.batches.filter(b=>b.status==='Completed').length+' full batches'} foot="completed + partial records"/></div><section className="card analytics-chart"><div className="card-heading"><div><div className="section-kicker"><TrendingUp size={14}/> COMPLETION TREND</div><h3>Tasks completed over time</h3><p className="muted small">Based on actual history. Empty days remain zero.</p></div></div><div className="chart-wrap tall">{weeklyStats.every(s=>s.tasks===0)?<EmptyState icon={BarChart3} title="No activity to chart yet" detail="Your chart will fill in automatically when you save batches."/>:<ResponsiveContainer width="100%" height="100%"><AreaChart data={range==='7 days'?weeklyStats:(()=>{const d=Array.from({length:30},(_,i)=>{const x=new Date();x.setDate(x.getDate()-(29-i));const key=todayKey(x);return {day:shortDate(key),tasks:data.batches.filter(b=>b.date===key).reduce((n,b)=>n+b.tasks,0),active:data.batches.filter(b=>b.date===key).reduce((n,b)=>n+b.activeSeconds,0)}});return d;})()} margin={{top:15,right:8,left:-10,bottom:4}}><defs><linearGradient id="anGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#8b78ff" stopOpacity={0.26}/><stop offset="95%" stopColor="#8b78ff" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="var(--chart-grid)" vertical={false}/><XAxis dataKey="day" tick={{fill:'var(--text-muted)',fontSize:11}} axisLine={false} tickLine={false}/><YAxis allowDecimals={false} tick={{fill:'var(--text-muted)',fontSize:11}} axisLine={false} tickLine={false}/><Tooltip contentStyle={{background:'var(--popover)',border:'1px solid var(--border)',borderRadius:12,color:'var(--text)',fontSize:12}}/><Area dataKey="tasks" name="Tasks completed" stroke="#927dff" strokeWidth={2.5} fill="url(#anGradient)"/></AreaChart></ResponsiveContainer>}</div></section><div className="analytics-bottom-grid"><section className="card analytics-panel"><div className="section-kicker"><FolderKanban size={14}/> PROJECT COMPARISON</div><h3>Where work happens</h3>{data.projects.filter(p=>!p.archived).map(p=>{const tasks=data.batches.filter(b=>b.projectId===p.id).reduce((n,b)=>n+b.tasks,0);const active=data.batches.filter(b=>b.projectId===p.id).reduce((n,b)=>n+b.activeSeconds,0);return <div className="compare-row" key={p.id}><div className="compare-heading"><i style={{background:p.color}}/><b>{p.name}</b><span>{tasks.toLocaleString()} tasks</span></div><div className="progress-track"><div className="progress-fill" style={{background:p.color,width:`${allTasks?tasks/allTasks*100:0}%`}}/></div><small>{fmt(active)} active time · {active? (tasks/(active/3600)).toFixed(1)+' tasks/hr':'Not enough data yet'}</small></div>})}{!data.projects.some(p=>!p.archived)&&<p className="muted small">Create a project to get started.</p>}</section><section className="card analytics-panel"><div className="section-kicker"><Trophy size={14}/> PERSONAL RECORDS</div><h3>Your milestones</h3><div className="record-row"><span className="record-icon"><Target size={16}/></span><div><b>Most tasks in one batch</b><small>From completed history</small></div><strong>{data.batches.length?Math.max(...data.batches.map(b=>b.tasks)).toLocaleString():'—'}</strong></div><div className="record-row"><span className="record-icon blue"><Clock3 size={16}/></span><div><b>Longest active batch</b><small>Active time, not wall time</small></div><strong>{data.batches.length?fmt(Math.max(...data.batches.map(b=>b.activeSeconds))):'—'}</strong></div><div className="record-row"><span className="record-icon green"><Flame size={16}/></span><div><b>Current work streak</b><small>Consecutive days with recorded tasks</small></div><strong>{streak} days</strong></div><div className="analytics-note"><CircleHelp size={15}/><span>Analytics use saved records only. MomentumFlow never fills gaps with sample data.</span></div></section></div></>}
        {page==='Achievements'&&<><PageIntro eyebrow="RECOGNIZE REAL PROGRESS" title="Achievements" subtitle="Every badge is earned from actual work recorded in your history." action={<span className="level-chip"><Trophy size={15}/> Level {level}</span>}/><section className="card level-card"><div className="level-medal"><Trophy size={30}/><span>{level}</span></div><div className="level-main"><span className="section-kicker">YOUR EXPERIENCE</span><h2>Level {level} <span>· {level===1?'Getting started':level<4?'Building momentum':'Consistent contributor'}</span></h2><p>Each completed batch contributes experience. Partial work counts, too.</p><div className="level-progress"><div className="progress-track"><div className="progress-fill" style={{width:`${levelXp/250*100}%`}}/></div><div><b>{levelXp} / 250 XP</b><span>{250-levelXp} XP to Level {level+1}</span></div></div></div><div className="level-total"><b>{totalXp}</b><span>TOTAL XP</span></div></section><div className="achievement-heading"><div><h3>Milestone collection</h3><p className="muted small">Unlocks update automatically as you record progress.</p></div><span>{[data.batches.length>0,allTasks>=100,allTasks>=500,completed>=goal.target&&goal.target>0,streak>=3,streak>=7,allActive>=3600].filter(Boolean).length} / 7 unlocked</span></div><div className="achievement-grid">{[{title:'First batch',detail:'Save your first batch record',icon:Layers3,unlocked:data.batches.length>0,color:'purple'},{title:'100 tasks',detail:'Complete 100 actual tasks',icon:Target,unlocked:allTasks>=100,color:'blue'},{title:'500 tasks',detail:'Complete 500 actual tasks',icon:Zap,unlocked:allTasks>=500,color:'orange'},{title:'Daily target',detail:'Reach today’s selected project goal',icon:Goal,unlocked:goal.target>0&&completed>=goal.target,color:'green'},{title:'Consistency builder',detail:'Record work on 3 consecutive days',icon:Flame,unlocked:streak>=3,color:'orange'},{title:'Seven-day streak',detail:'Record work on 7 consecutive days',icon:CalendarDays,unlocked:streak>=7,color:'purple'},{title:'One focused hour',detail:'Record 60 minutes of active work',icon:Clock3,unlocked:allActive>=3600,color:'blue'}].map(a=><article className={`achievement-card card ${a.unlocked?'unlocked':''}`} key={a.title}><span className={`achievement-symbol ${a.color}`}><a.icon size={23}/>{a.unlocked&&<i><Check size={11}/></i>}</span><div><b>{a.title}</b><p>{a.detail}</p></div><span className={`achievement-state ${a.unlocked?'earned':''}`}>{a.unlocked?'Unlocked':'Locked'}</span></article>)}</div><div className="history-disclaimer"><ShieldCheck size={15}/> XP is derived from saved batch events. Repeated refreshes do not award duplicate XP.</div></>}
        {page==='Daily Reports'&&<><PageIntro eyebrow="REFLECT, THEN RESET" title="Daily report" subtitle="A thoughtful review of your day. Celebrate what happened, then choose what comes next." action={<button className="button button-secondary" onClick={()=>{const summary=`MomentumFlow daily report — ${day}\nProject: ${project?.name??'None'}\nTarget: ${goal.target}\nCompleted: ${completed}\nRemaining: ${remaining}\nActive time: ${fmt(todayActive)}\nBreak time: ${fmt(todayBreak)}\nPace: ${rate?rate.toFixed(1)+' tasks/hr':'Not enough data yet'}\nBatches: ${todaysBatches.length}\nXP total: ${totalXp}\n\nWent well: ${reflectionDraft.wentWell}\nSlowed down: ${reflectionDraft.slowedDown}\nImprove: ${reflectionDraft.improve}\nTomorrow target: ${reflectionDraft.tomorrow}`;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([summary],{type:'text/plain'}));a.download=`momentumflow-report-${day}.txt`;a.click();notify('Daily report exported.')}}><Download size={15}/> Export report</button>}/><section className="report-hero card"><div><span className="section-kicker"><CalendarDays size={14}/> {dateLabel.toUpperCase()}</span><h2>{pct>=100?'You reached your target.':completed>0?'Your effort counts.':'Your day is still yours to shape.'}</h2><p>Here’s the picture from your recorded work. No estimates presented as fact, and no pressure to make every day look the same.</p></div><div className="report-ring" style={{'--progress':`${visualPct*3.6}deg`} as React.CSSProperties}><strong>{Math.round(visualPct)}<small>%</small></strong><span>of target</span></div></section><div className="report-metrics-grid"><div className="report-metric card"><span>DAILY TARGET</span><b>{goal.target.toLocaleString()}</b><small>tasks planned</small></div><div className="report-metric card"><span>COMPLETED</span><b>{completed.toLocaleString()}</b><small>{remaining.toLocaleString()} remaining</small></div><div className="report-metric card"><span>ACTIVE TIME</span><b>{fmt(todayActive)}</b><small>excluding breaks</small></div><div className="report-metric card"><span>BREAK TIME</span><b>{fmt(todayBreak)}</b><small>time away from work</small></div><div className="report-metric card"><span>OBSERVED PACE</span><b>{rate?rate.toFixed(1):'—'}</b><small>{rate?'tasks per active hour':'Not enough data yet'}</small></div><div className="report-metric card"><span>BATCHES SAVED</span><b>{todaysBatches.length}</b><small>{todaysBatches.filter(b=>b.status==='Completed').length} full · {todaysBatches.filter(b=>b.status==='Partial').length} partial</small></div></div><section className="card reflection-card"><div className="section-kicker"><Pencil size={14}/> DAILY REFLECTION</div><h3>What did you learn today?</h3><p className="muted small">A few honest notes can make tomorrow easier. Your reflection stays on this browser.</p><div className="reflection-grid"><label>What went well?<textarea rows={3} value={reflectionDraft.wentWell} onChange={e=>setReflectionDraft(r=>({...r,wentWell:e.target.value}))} placeholder="What helped you make progress?"/></label><label>What slowed you down?<textarea rows={3} value={reflectionDraft.slowedDown} onChange={e=>setReflectionDraft(r=>({...r,slowedDown:e.target.value}))} placeholder="Anything that made work harder?"/></label><label>One thing to improve<textarea rows={3} value={reflectionDraft.improve} onChange={e=>setReflectionDraft(r=>({...r,improve:e.target.value}))} placeholder="One small adjustment for next time…"/></label><label>Tomorrow's target<input type="number" min="0" value={reflectionDraft.tomorrow} onChange={e=>setReflectionDraft(r=>({...r,tomorrow:e.target.value}))}/></label></div><div className="reflection-actions"><span><ShieldCheck size={14}/> Saved locally when you click save</span><button className="button button-primary" onClick={saveReflection}><Check size={15}/> Save reflection</button></div></section></>}
        {page==='Settings'&&<><PageIntro eyebrow="MAKE IT YOURS" title="Settings" subtitle="Tune MomentumFlow to fit the way you like to work."/><div className="settings-layout"><section className="card settings-card"><div className="settings-section-head"><div className="settings-leading-icon"><Settings2 size={18}/></div><div><h3>Profile</h3><p>Make the dashboard feel like your space.</p></div></div><label className="settings-field">Display name<input value={nameDraft} onChange={e=>setNameDraft(e.target.value)} placeholder="Your name"/></label><div className="settings-field"><span>Profile preview</span><div className="profile-preview"><div className="profile-avatar large">{initials(nameDraft)}</div><div><b>{nameDraft||'Your name'}</b><small>Level {level} · {totalXp} XP</small></div></div></div><button className="button button-primary" onClick={()=>{if(!nameDraft.trim()){notify('Enter a display name.');return;}update(d=>({...d,displayName:nameDraft.trim()}));notify('Profile updated.')}}><Check size={15}/> Save profile</button></section><section className="card settings-card"><div className="settings-section-head"><div className="settings-leading-icon purple"><Sun size={18}/></div><div><h3>Appearance</h3><p>Choose the environment that feels right.</p></div></div><div className="theme-options"><button className={data.theme==='dark'?'theme-option chosen':'theme-option'} onClick={()=>update(d=>({...d,theme:'dark'}))}><span className="theme-preview theme-dark"><Moon size={20}/></span><b>Dark mode</b><small>Midnight surfaces, soft glow</small>{data.theme==='dark'&&<Check size={15}/>}</button><button className={data.theme==='light'?'theme-option chosen':'theme-option'} onClick={()=>update(d=>({...d,theme:'light'}))}><span className="theme-preview theme-light"><Sun size={20}/></span><b>Light mode</b><small>Clean and bright workspace</small>{data.theme==='light'&&<Check size={15}/>}</button></div></section><section className="card settings-card"><div className="settings-section-head"><div className="settings-leading-icon green"><Download size={18}/></div><div><h3>Your data</h3><p>Everything is stored locally in this browser. There is no cloud sync.</p></div></div><div className="data-action-row"><div><b>Export backup</b><small>Download projects, history, goals and reflections.</small></div><button className="button button-secondary" onClick={exportData}><Download size={15}/> Export JSON</button></div><div className="data-action-row"><div><b>Import backup</b><small>Restore a previously exported MomentumFlow file.</small></div><label className="button button-secondary upload-button"><Upload size={15}/> Choose file<input type="file" accept="application/json,.json" onChange={e=>importData(e.target.files?.[0])}/></label></div><div className="data-action-row danger-row"><div><b>Reset all data</b><small>Delete local projects, sessions, records and settings.</small></div><button className="button button-danger" onClick={()=>setResetOpen(true)}>Reset data</button></div></section><section className="card settings-card about-card"><div className="settings-section-head"><div className="settings-leading-icon orange"><ShieldCheck size={18}/></div><div><h3>About MomentumFlow</h3><p>Built for consistent, sustainable progress.</p></div></div><div className="about-list"><div><span>Data storage</span><b>Local browser storage</b></div><div><span>Timer</span><b>Timestamp-based</b></div><div><span>Active pace</span><b>Breaks excluded</b></div><div><span>Version</span><b>1.0.0</b></div></div></section></div></>}
      </div>
      <footer className="app-footer"><span><span className="footer-brand-mark">✳</span> momentumflow <i/> Made for sustainable progress</span><span><ShieldCheck size={13}/> Local-first · Your work, your pace</span></footer>
    </main>
    {goalOpen&&<Modal title="Edit daily goal" subtitle={`Set today's objective for ${project?.name??'your project'}.`} onClose={()=>setGoalOpen(false)}><div className="form-grid"><label>Task target<input type="number" min="0" value={goalDraft.target} onChange={e=>setGoalDraft(g=>({...g,target:Number(e.target.value)}))}/><small>Total tasks to complete for this project today.</small></label><label>Default batch size<input type="number" min="1" value={goalDraft.batchSize} onChange={e=>setGoalDraft(g=>({...g,batchSize:Number(e.target.value)}))}/><small>The suggested size for your next batch.</small></label><label>Planned work duration (minutes)<input type="number" min="1" value={goalDraft.plannedMinutes} onChange={e=>setGoalDraft(g=>({...g,plannedMinutes:Number(e.target.value)}))}/><small>Planning reference, not a timer deadline.</small></label><label>Project<select value={project?.id??''} onChange={e=>{setActiveProject(e.target.value);const p=data.projects.find(x=>x.id===e.target.value);if(p)setGoalDraft(currentGoal(data,p));}}>{data.projects.filter(p=>!p.archived).map(p=><option value={p.id} key={p.id}>{p.name}</option>)}</select></label><label className="wide-field">Note (optional)<textarea rows={3} value={goalDraft.notes} onChange={e=>setGoalDraft(g=>({...g,notes:e.target.value}))} placeholder="What matters most today?"/></label></div><div className="modal-actions"><button className="button button-secondary" onClick={()=>setGoalOpen(false)}>Cancel</button><button className="button button-primary" onClick={saveGoal}><Check size={15}/> Save daily goal</button></div></Modal>}
    {newProjectOpen&&<Modal title="Create a project" subtitle="Give this kind of work its own target and history." onClose={()=>setNewProjectOpen(false)}><div className="form-grid"><label className="wide-field">Project name<input autoFocus value={projectDraft.name} onChange={e=>setProjectDraft(p=>({...p,name:e.target.value}))} placeholder="e.g. Telugu audio review"/></label><label>Category<select value={projectDraft.category} onChange={e=>setProjectDraft(p=>({...p,category:e.target.value}))}>{['AI Operations','Annotation','Research','Development','Study','Personal','Custom'].map(c=><option key={c}>{c}</option>)}</select></label><label>Daily target<input type="number" min="0" value={projectDraft.target} onChange={e=>setProjectDraft(p=>({...p,target:e.target.value}))}/></label><label>Default batch size<input type="number" min="1" value={projectDraft.batchSize} onChange={e=>setProjectDraft(p=>({...p,batchSize:e.target.value}))}/></label><label>Project color<div className="color-options">{['#8a78ff','#29c6b7','#5da9ff','#f5a65b','#e779ac','#62bd84'].map(c=><button key={c} className={projectDraft.color===c?'color-pick chosen':'color-pick'} style={{background:c}} onClick={()=>setProjectDraft(p=>({...p,color:c}))} aria-label={'Color '+c}>{projectDraft.color===c&&<Check size={13}/>}</button>)}</div></label></div><div className="modal-actions"><button className="button button-secondary" onClick={()=>setNewProjectOpen(false)}>Cancel</button><button className="button button-primary" onClick={addProject}><Plus size={15}/> Create project</button></div></Modal>}
    {resetOpen&&<Modal title="Reset MomentumFlow?" subtitle="This permanently removes all MomentumFlow data saved in this browser." onClose={()=>setResetOpen(false)}><div className="reset-warning"><span><Archive size={19}/></span><div><b>This action cannot be undone.</b><p>Export a backup first if you want to keep your projects, batches, XP, goals and reflections.</p></div></div><div className="modal-actions"><button className="button button-secondary" onClick={()=>setResetOpen(false)}>Keep my data</button><button className="button button-danger" onClick={()=>{localStorage.removeItem(STORAGE);setData({...starter,projects:starter.projects.map(p=>({...p})),goals:{},batches:[],session:null,xpEvents:{},reflections:{}});setActiveProject(starter.projects[0].id);setPage('Dashboard');setResetOpen(false);notify('Local MomentumFlow data has been reset.')}}>Reset everything</button></div></Modal>}
    {toast&&<div className="toast" role="status"><span><Check size={15}/></span>{toast}<button aria-label="Dismiss notification" onClick={()=>setToast('')}><X size={14}/></button></div>}
  </div>;
}

function StatCard({icon:Icon,iconClass,label,value,trend,trendUp,foot}:{icon:LucideIcon;iconClass:string;label:string;value:string;trend:string;trendUp:boolean;foot:string}) {
 return <article className="stat-card card"><div className="stat-top"><span className={`stat-icon ${iconClass}`}><Icon size={17}/></span><button className="stat-more" aria-label={label+' details'} title={label}><MoreHorizontal size={17}/></button></div><span className="stat-label">{label}</span><strong className="stat-value">{value}</strong><div className={`stat-trend ${trendUp?'positive':''}`}>{trendUp?<ArrowUpRight size={13}/>:<ArrowDownRight size={13}/>}<span>{trend}</span></div><small className="stat-foot">{foot}</small></article>;
}
function PageIntro({eyebrow,title,subtitle,action}:{eyebrow:string;title:string;subtitle:string;action?:React.ReactNode}) {
 return <div className="page-intro secondary-intro"><div><div className="eyebrow"><span className="eyebrow-dot"/>{eyebrow}</div><h1>{title}</h1><p>{subtitle}</p></div>{action&&<div className="intro-actions">{action}</div>}</div>;
}
function EmptyState({icon:Icon,title,detail}:{icon:LucideIcon;title:string;detail:string}) {
 return <div className="empty-state"><span><Icon size={22}/></span><b>{title}</b><p>{detail}</p></div>;
}
function Modal({title,subtitle,onClose,children}:{title:string;subtitle:string;onClose:()=>void;children:React.ReactNode}) {
 useEffect(()=>{const handler=(e:KeyboardEvent)=>{if(e.key==='Escape')onClose();};window.addEventListener('keydown',handler);return()=>window.removeEventListener('keydown',handler);},[onClose]);
 return <div className="modal-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div className="modal-panel" role="dialog" aria-modal="true" aria-labelledby="modal-heading"><div className="modal-header"><div><h2 id="modal-heading">{title}</h2><p>{subtitle}</p></div><button className="icon-button" onClick={onClose} aria-label="Close dialog"><X size={17}/></button></div>{children}</div></div>;
}
